from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            y0 = min(y for y, _ in cells)
            y1 = max(y for y, _ in cells)
            x0 = min(x for _, x in cells)
            x1 = max(x for _, x in cells)
            area = (y1 - y0 + 1) * (x1 - x0 + 1)
            # Solid objects are preserved/repaired to their bounding rectangle;
            # isolated colored specks are noise and disappear.
            if len(cells) >= 4 and area >= 4 and len(cells) / area >= 0.60:
                for y in range(y0, y1 + 1):
                    for x in range(x0, x1 + 1):
                        out[y][x] = color
    return out


if __name__ == '__main__':
    sample = [[8, 8, 8, 8, 6, 8], [8, 2, 2, 8, 8, 8], [8, 2, 2, 8, 7, 8]]
    assert transform(sample) == [[8, 8, 8, 8, 8, 8], [8, 2, 2, 8, 8, 8], [8, 2, 2, 8, 8, 8]]
