def transform(grid):
    h, w = len(grid), len(grid[0])
    # Background is the most common color; the non-background pattern is a
    # set of filled rectangles obscured by rare single-cell noise.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    # Each row/column rectangle component of a primary color is repaired by
    # replacing isolated intrusions inside the object's bounding box.
    seen = [[False] * w for _ in range(h)]
    from collections import deque
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r,c)]); seen[r][c] = True; cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
