def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # Detect the many rectangular objects by looking for a 2x2 solid seed,
    # then expand its color to the maximal surrounding rectangle where nearly
    # every cell is that color; sparse alien marker cells are tolerated.
    out = [[background for _ in range(w)] for _ in range(h)]
    for color in set(counts) - {background}:
        seeds = []
        for r in range(h-1):
            for c in range(w-1):
                if all(grid[y][x] == color for y in (r,r+1) for x in (c,c+1)):
                    seeds.append((r,c))
        # Candidate rectangular extents around each seed; retain maximal area
        # with high color purity, independently so disjoint objects survive.
        rects = set()
        for r,c in seeds:
            for r0 in range(r+1):
                for r1 in range(r+1,h):
