from pathlib import Path
p=Path('programs/task-1550b62f.py')
p.write_text('''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background for _ in range(w)] for _ in range(h)]
    # Solid rectangular objects have at least two adjacent rows containing
    # repeated spans of their color; isolated non-object marks are discarded.
    for color in set(v for row in grid for v in row) - {background}:
        spans = {}
        for r, row in enumerate(grid):
            c = 0
            while c < w:
                if row[c] != color:
                    c += 1
                    continue
                c0 = c
                while c + 1 < w and row[c + 1] == color:
                    c += 1
                if c - c0 + 1 >= 2:
                    spans.setdefault((c0, c), []).append(r)
                c += 1
        for (c0, c1), rows in spans.items():
            rows = sorted(set(rows))
            groups = []
            for r in rows:
                if not groups or r > groups[-1][-1] + 1:
                    groups.append([r])
                else:
                    groups[-1].append(r)
            for group in groups:
                if len(group) < 2:
                    continue
                for r in range(group[0], group[-1] + 1):
                    for c in range(c0, c1 + 1):
                        out[r][c] = color
    return out
''')
